'use strict';

const fs = require('node:fs/promises');
const { assert, path, fileURL, pieces, withBrowser, observe, assertOffline, assertRegions, assertAccessibility, assertGeometry } = require('./support.cjs');

// n011 protects real offline composition at its strongest boundary: the actual
// integrated file page. It catches missing/miswired scripts, premature results,
// cross-piece interference, lost results, keyboard failures and responsive
// overflow. Standalone script fixtures and the JS-disabled n010 cannot prove
// this composition. Screenshots support a separate human appearance judgment.
async function main() {
  assert.ok(process.env.SELDON_EVIDENCE_DIR, 'SELDON_EVIDENCE_DIR is required for product evidence');
  const evidence = process.env.SELDON_EVIDENCE_DIR;
  await fs.mkdir(evidence, { recursive: true });
  await withBrowser(async browser => {
    const observations = [];
    for (const [size, width, height] of [['desktop', 1280, 900], ['mobile', 375, 812]]) {
      const context = await browser.newContext({ viewport: { width, height }, reducedMotion: 'reduce' });
      const page = await context.newPage();
      const record = observe(page); // all observers are attached before navigation
      await page.goto(fileURL('index.html'), { waitUntil: 'load' });
      assert.equal(await page.title(), 'Foundation');
      assert.equal(await page.getByRole('heading', { name: 'Foundation', level: 1, exact: true }).count(), 1);
      const expected = ['', '', ''];
      await assertRegions(page, expected);
      await assertAccessibility(page, expected);
      const initialGeometry = await assertGeometry(page);
      await page.screenshot({ path: path.join(evidence, `page-${size}-initial.png`), fullPage: true });
      const unchangedButtons = await page.locator('button').evaluateAll(elements => elements.map(element => element.outerHTML));

      for (let i = 0; i < pieces.length; i++) {
        const button = page.getByRole('button', { name: pieces[i].name, exact: true });
        if (size === 'desktop') {
          await button.click();
        } else {
          // A fresh mobile page starts with no pointer/focus intervention. Each
          // Tab must reach the next named control; screenshots retain that state.
          await page.keyboard.press('Tab');
          assert.equal(await button.evaluate(element => document.activeElement === element), true, 'natural Tab order reaches every named control');
          assert.equal(await button.evaluate(element => element.matches(':focus-visible')), true, 'keyboard focus is visible');
          const focus = await button.evaluate(element => {
            const style = getComputedStyle(element);
            return { style: style.outlineStyle, width: parseFloat(style.outlineWidth), offset: parseFloat(style.outlineOffset), color: style.outlineColor };
          });
          assert.equal(focus.style, 'solid');
          assert.ok(focus.width >= 3 && focus.offset >= 3, 'clear focus outline has separation and thickness');
          assert.equal(focus.color, 'rgb(255, 196, 92)', 'amber focus contrasts with midnight');
          await page.screenshot({ path: path.join(evidence, `page-mobile-focus-${pieces[i].key}.png`), fullPage: true });
          await page.keyboard.press(i === 1 ? 'Space' : 'Enter');
        }
        expected[i] = pieces[i].text;
        await assertRegions(page, expected);
        await assertGeometry(page);
        if (size === 'mobile') {
          // Exercise both native keys on every control, including repeat use.
          for (const key of ['Enter', 'Space']) {
            await page.keyboard.press(key);
            await assertRegions(page, expected);
          }
        }
      }
      if (size === 'desktop') {
        for (const piece of pieces) {
          await page.getByRole('button', { name: piece.name, exact: true }).click();
          await assertRegions(page, expected);
        }
      }
      assert.deepEqual(await page.locator('button').evaluateAll(elements => elements.map(element => element.outerHTML)), unchangedButtons, 'reveals retain the original controls and relationships');
      const finalGeometry = await assertGeometry(page);
      const accessibility = await assertAccessibility(page, expected);
      await page.screenshot({ path: path.join(evidence, `page-${size}-revealed.png`), fullPage: true });
      assertOffline(record, ['index.html', 'styles.css', ...pieces.map(piece => piece.script)]);
      assert.equal(page.url(), fileURL('index.html'), 'page remains at the actual local product');
      assert.equal(context.pages().length, 1, 'no extra browsing surfaces');
      await fs.writeFile(path.join(evidence, `page-${size}-accessibility.json`), JSON.stringify(accessibility, null, 2));
      observations.push({ size, viewport: { width, height }, initialGeometry, finalGeometry, ...record });
      await context.close();
    }
    await fs.writeFile(path.join(evidence, 'page-product-observations.json'), JSON.stringify({
      check: 'n011', passed: true, actualFilePage: true, independentExactReveals: true,
      retainedResults: true, nativeEnterAndSpace: true, repeatedActivation: true,
      accessibilityExposure: true, offlineIntegration: true, observations,
      appearanceJudgedByAssertions: false,
    }, null, 2));
    console.log(JSON.stringify({ check: 'n011', passed: true, offlineIntegration: true, desktopAnd375px: true,
      exactIndependentReveals: true, nativeKeyboardAndRepeat: true, accessibilityExposure: true, evidence }));
  });
}

main().catch(error => { console.error(error); process.exitCode = 1; });

