'use strict';

const assert = require('node:assert/strict');
const path = require('node:path');
const { pathToFileURL } = require('node:url');
const { chromium } = require('C:\\Users\\oren\\codex-harness\\ui\\node_modules\\.pnpm\\playwright-core@1.59.1\\node_modules\\playwright-core');

const root = path.resolve(__dirname, '../..');
const fileURL = relative => pathToFileURL(path.join(root, relative)).href;
const pieces = [
  { key: 'hello', name: 'Play greeting', region: 'Greeting message', text: 'Hello, world!', script: 'scripts/hello.js' },
  { key: 'name', name: 'Play introduction', region: 'Introduction message', text: 'My name is Seldon', script: 'scripts/name.js' },
  { key: 'foundation', name: 'Play Foundation', region: 'Foundation message', text: 'This is the Foundation', script: 'scripts/foundation.js' },
];

async function withBrowser(run) {
  const browser = await chromium.launch({
    headless: true,
    executablePath: 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe',
    timeout: 15000,
  });
  try {
    await run(browser);
  } finally {
    await browser.close();
    console.log(JSON.stringify({ edgeClosed: true }));
  }
}

function observe(page) {
  const record = { requests: [], failedRequests: [], errors: [], dialogs: [], navigations: [], popups: [] };
  page.setDefaultTimeout(5000);
  page.setDefaultNavigationTimeout(10000);
  page.on('request', request => record.requests.push(request.url()));
  page.on('requestfailed', request => record.failedRequests.push({ url: request.url(), failure: request.failure() }));
  page.on('pageerror', error => record.errors.push(error.message));
  page.on('console', message => { if (message.type() === 'error') record.errors.push(message.text()); });
  page.on('dialog', async dialog => {
    record.dialogs.push({ type: dialog.type(), message: dialog.message() });
    await dialog.dismiss();
  });
  page.on('framenavigated', frame => record.navigations.push(frame.url()));
  page.on('popup', popup => record.popups.push(popup.url()));
  return record;
}

function assertOffline(record, expectedResources) {
  assert.deepEqual(record.errors, [], 'no console errors or page errors');
  assert.deepEqual(record.failedRequests, [], 'all local resources load successfully');
  assert.deepEqual(record.dialogs, [], 'activation opens no dialogs');
  assert.deepEqual(record.popups, [], 'activation opens no additional pages');
  assert.deepEqual(record.navigations, [fileURL('index.html')], 'only the initial file navigation occurs');
  assert.deepEqual([...record.requests].sort(), expectedResources.map(fileURL).sort(), 'only the exact local product resources load, once each');
}

async function assertRegions(page, expected) {
  const actual = [];
  for (const piece of pieces) actual.push(await page.locator(`#${piece.key}-message`).textContent());
  assert.deepEqual(actual, expected, 'exact independent messages; unchanged siblings and retained prior results');
  for (let i = 0; i < pieces.length; i++) {
    if (expected[i]) {
      assert.equal(await page.getByText(expected[i], { exact: true }).count(), 1, 'one inline instance of each revealed message');
      assert.equal(await page.locator(`#${pieces[i].key}-message`).isVisible(), true, 'revealed text is visible');
    } else {
      assert.equal(await page.getByText(pieces[i].text, { exact: true }).count(), 0, 'unplayed message text is absent');
    }
  }
}

async function assertAccessibility(page, expected) {
  const session = await page.context().newCDPSession(page);
  try {
    const { nodes } = await session.send('Accessibility.getFullAXTree');
    for (let i = 0; i < pieces.length; i++) {
      const piece = pieces[i];
      const button = nodes.filter(node => !node.ignored && node.role?.value === 'button' && node.name?.value === piece.name);
      assert.equal(button.length, 1, `accessible native control: ${piece.name}`);
      const regions = nodes.filter(node => !node.ignored && node.role?.value === 'status' && node.name?.value === piece.region);
      assert.equal(regions.length, 1, `always-exposed message region: ${piece.region}`);
      const properties = Object.fromEntries(regions[0].properties.map(property => [property.name, property.value.value]));
      assert.equal(properties.live, 'polite', 'accessibility tree exposes polite announcements');
      assert.equal(properties.atomic, true, 'accessibility tree exposes atomic announcements');
      if (expected[i]) {
        const descendants = new Set(regions[0].childIds || []);
        let textExposed = false;
        for (const node of nodes) {
          if (descendants.has(node.nodeId)) {
            if (!node.ignored && node.name?.value === expected[i]) textExposed = true;
            for (const id of node.childIds || []) descendants.add(id);
          }
        }
        assert.equal(textExposed, true, 'exact revealed message is exposed beneath its own accessible status');
      }
    }
    return nodes;
  } finally {
    await session.detach();
  }
}

async function assertGeometry(page) {
  const geometry = await page.evaluate(() => ({
    viewport: innerWidth,
    documentWidth: document.documentElement.scrollWidth,
    bodyWidth: document.body.scrollWidth,
    buttons: [...document.querySelectorAll('button')].map(element => {
      const r = element.getBoundingClientRect();
      return { left: r.left, right: r.right, top: r.top, width: r.width, height: r.height };
    }),
    messages: [...document.querySelectorAll('[role="status"]')].map(element => {
      const r = element.getBoundingClientRect();
      return { left: r.left, right: r.right, clientWidth: element.clientWidth, scrollWidth: element.scrollWidth };
    }),
  }));
  assert.equal(geometry.buttons.length, 3, 'three controls');
  assert.ok(geometry.documentWidth <= geometry.viewport && geometry.bodyWidth <= geometry.viewport, 'no horizontal page overflow');
  for (let i = 0; i < 3; i++) {
    const b = geometry.buttons[i];
    assert.ok(Math.abs(b.top - geometry.buttons[0].top) < 1, 'all controls share a row');
    assert.ok(Math.abs(b.width - geometry.buttons[0].width) < 1, 'three equally wide controls');
    assert.ok(b.left >= 0 && b.right <= geometry.viewport, 'control stays inside viewport');
    assert.ok(b.width >= 44 && b.height >= 44, 'control has a usable touch target');
    if (i) assert.ok(b.left > geometry.buttons[i - 1].right, 'controls have ordered, separated columns');
    const m = geometry.messages[i];
    assert.ok(m.left >= 0 && m.right <= geometry.viewport && m.scrollWidth <= m.clientWidth, 'message wraps without horizontal overflow');
  }
  return geometry;
}

module.exports = { assert, path, fileURL, pieces, withBrowser, observe, assertOffline, assertRegions, assertAccessibility, assertGeometry };

