:root {
  color-scheme: dark;
  --midnight: #0b1c30;
  --ivory: #fff4dc;
  --amber: #ffc45c;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--midnight);
  color: var(--ivory);
  font-family: Arial, sans-serif;
  line-height: 1.5;
}

.console {
  width: min(1120px, calc(100% - 112px));
  margin-inline: auto;
}

.masthead {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  padding-block: 28px 22px;
  border-bottom: 1px solid var(--ivory);
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

p {
  margin: 0;
}

.introduction {
  padding-block: 76px 64px;
}

.eyebrow {
  margin-bottom: 14px;
  color: var(--amber);
  font-size: 12px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

h1,
h2 {
  margin: 0;
  font-family: Georgia, serif;
  font-weight: 400;
}

h1 {
  font-size: clamp(64px, 8vw, 112px);
  line-height: 1.08;
  letter-spacing: -0.045em;
}

.lead {
  margin-top: 24px;
  font-size: 19px;
}

.channels {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 32px;
}

.channel {
  min-width: 0;
  border-top: 2px solid var(--amber);
  padding-top: 18px;
}

.channel-number {
  color: var(--amber);
  font-size: 12px;
  letter-spacing: 0.12em;
}

h2 {
  margin-block: 14px 26px;
  font-size: 30px;
  line-height: 1.2;
}

button {
  display: flex;
  align-items: center;
  gap: 18px;
  width: 100%;
  min-height: 76px;
  padding: 20px;
  border: 1px solid var(--amber);
  border-radius: 0;
  background: #142c44;
  color: var(--ivory);
  font-family: Arial, sans-serif;
  font-size: 16px;
  line-height: 1.35;
  text-align: left;
  cursor: pointer;
  transition: background-color 120ms linear;
}

button:hover {
  background: #213f5b;
}

button:active {
  background: var(--midnight);
}

button:focus-visible {
  outline: 3px solid var(--amber);
  outline-offset: 4px;
  background: #213f5b;
}

.play-symbol {
  flex: none;
  color: var(--amber);
  font-size: 19px;
  line-height: 1;
}

.message {
  min-height: 88px;
  padding-top: 24px;
  overflow-wrap: anywhere;
  font-size: 19px;
  line-height: 1.5;
}

footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-top: 44px;
  padding-block: 24px 32px;
  border-top: 1px solid var(--ivory);
  font-size: 13px;
  line-height: 1.6;
}

.end-mark {
  color: var(--amber);
  font-family: Georgia, serif;
  font-size: 32px;
  line-height: 1;
}

